-- Упражнения книги 17, глава 21 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-vlan-device', 0, 'func', 'Имя VLAN-интерфейса', 'На хосте сеть с меткой VLAN получает подинтерфейс «карта.номер». Напишите функцию vlan_device(nic, vlan): если vlan равен None, верните nic без изменений; если vlan — целое от 1 до 4094 включительно, верните строку вида "eth0.100"; иначе верните пустую строку. Имя интерфейса в Linux не длиннее 15 символов: если получившееся имя (в том числе без метки) длиннее, тоже верните пустую строку.', 'def vlan_device(nic, vlan):
    pass
', 'Сначала постройте имя, потом проверьте его длину.', '{"func": "vlan_device", "tests": [{"args": ["eth0", 100], "expected": "eth0.100"}, {"args": ["eth0", null], "expected": "eth0"}, {"args": ["eth0", 0], "expected": ""}, {"args": ["eth0", 4095], "expected": ""}, {"args": ["eth0", 4094], "expected": "eth0.4094"}, {"args": ["bond0", 42], "expected": "bond0.42"}, {"args": ["enp130s0f1np1", 5], "expected": "enp130s0f1np1.5"}, {"args": ["enp130s0f1np1", 55], "expected": ""}, {"args": ["a-very-long-nic-name", null], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-network-name', 1, 'func', 'Допустимое имя сети', 'Имя сети становится именем bridge на хосте, поэтому на него наложены ограничения. В нашей модели имя допустимо, если выполнены все условия: длина от 1 до 15 символов; только ASCII-буквы, цифры, подчёркивание и дефис; имя не начинается с дефиса. Напишите функцию is_valid_network_name(name): верните True или False.', 'def is_valid_network_name(name):
    pass
', 'Проверьте длину, первый символ и каждый символ отдельно; для ASCII есть c.isascii().', '{"func": "is_valid_network_name", "tests": [{"args": ["ovirtmgmt"], "expected": true}, {"args": [""], "expected": false}, {"args": ["aaaaaaaaaaaaaaa"], "expected": true}, {"args": ["aaaaaaaaaaaaaaaa"], "expected": false}, {"args": ["vm net"], "expected": false}, {"args": ["net.1"], "expected": false}, {"args": ["-net"], "expected": false}, {"args": ["net-1_b"], "expected": true}, {"args": ["mgmt/1"], "expected": false}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-required-missing', 2, 'func', 'Хосты без обязательных сетей', 'Хост, на котором не работает хотя бы одна обязательная сеть кластера, становится NonOperational. Напишите функцию nonoperational_hosts(required, hosts): required — список имён обязательных сетей (могут повторяться), hosts — словарь «имя хоста → список сетей, которые на нём работают». Верните список кортежей (хост, отсортированный список недостающих обязательных сетей без повторов) только для хостов, у которых чего-то не хватает; список отсортирован по имени хоста.', 'def nonoperational_hosts(required, hosts):
    pass
', 'Переведите required в множество, вычтите множество сетей хоста.', '{"func": "nonoperational_hosts", "tests": [{"args": [["ovirtmgmt", "vm1"], {"h1": ["ovirtmgmt", "vm1"], "h2": ["ovirtmgmt"]}], "expected": [{"__tuple__": ["h2", ["vm1"]]}]}, {"args": [[], {"h1": []}], "expected": []}, {"args": [["a", "b"], {"h2": [], "h1": ["b"]}], "expected": [{"__tuple__": ["h1", ["a"]]}, {"__tuple__": ["h2", ["a", "b"]]}]}, {"args": [["a"], {}], "expected": []}, {"args": [["a", "a"], {"h": []}], "expected": [{"__tuple__": ["h", ["a"]]}]}, {"args": [["a"], {"h": ["a", "b", "c"]}], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-mtu-plan', 3, 'func', 'План MTU по картам', 'Карте хоста нужен MTU, равный максимуму MTU сетей на ней, а путь за картой (порт коммутатора) должен его пропускать. Напишите функцию mtu_plan(network_mtu, attachments, path_mtu): network_mtu — словарь «сеть → MTU» (сеть, которой нет в словаре, имеет 1500), attachments — список пар (сеть, карта), path_mtu — словарь «карта → MTU пути» (если карты нет, считайте 1500). Верните кортеж из двух элементов: словарь «карта → требуемый MTU» (только для карт из attachments) и отсортированный список карт, у которых MTU пути меньше требуемого.', 'def mtu_plan(network_mtu, attachments, path_mtu):
    pass
', 'Накапливайте максимум в словаре по карте, потом сравните с path_mtu.get(nic, 1500).', '{"func": "mtu_plan", "tests": [{"args": [{"a": 9000, "b": 1500}, [{"__tuple__": ["a", "eth0"]}, {"__tuple__": ["b", "eth0"]}, {"__tuple__": ["b", "eth1"]}], {"eth0": 9000, "eth1": 1500}], "expected": {"__tuple__": [{"eth0": 9000, "eth1": 1500}, []]}}, {"args": [{"a": 9000, "b": 1500}, [{"__tuple__": ["a", "eth0"]}, {"__tuple__": ["b", "eth0"]}, {"__tuple__": ["b", "eth1"]}], {"eth0": 1500, "eth1": 1500}], "expected": {"__tuple__": [{"eth0": 9000, "eth1": 1500}, ["eth0"]]}}, {"args": [{}, [{"__tuple__": ["c", "eth0"]}], {}], "expected": {"__tuple__": [{"eth0": 1500}, []]}}, {"args": [{"a": 9000}, [{"__tuple__": ["a", "bond0"]}], {}], "expected": {"__tuple__": [{"bond0": 9000}, ["bond0"]]}}, {"args": [{"a": 9000}, [], {}], "expected": {"__tuple__": [{}, []]}}, {"args": [{"a": 9000, "b": 2000}, [{"__tuple__": ["b", "eth5"]}, {"__tuple__": ["a", "eth2"]}], {"eth5": 1500, "eth2": 8000}], "expected": {"__tuple__": [{"eth5": 2000, "eth2": 9000}, ["eth2", "eth5"]]}}, {"args": [{"a": 1500}, [{"__tuple__": ["a", "e"]}], {"e": 9000}], "expected": {"__tuple__": [{"e": 1500}, []]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-static-ip', 4, 'func', 'Проверка статического адреса', 'Администратор задаёт хосту статический адрес. Напишите функцию check_static_ip(address, prefix, gateway) и верните первую сработавшую ошибку по порядку: "bad-prefix" — prefix не целое от 1 до 30; "bad-address" — address не корректный IPv4; "bad-gateway" — gateway не пустая строка и не корректный IPv4; "address-is-network" — адрес равен адресу сети; "address-is-broadcast" — адрес равен широковещательному; если gateway пустая строка, верните "ok"; "gateway-outside" — шлюз вне подсети; "gateway-is-self" — шлюз совпадает с адресом; "gateway-reserved" — шлюз равен адресу сети или широковещательному. Иначе верните "ok". Можно использовать модуль ipaddress.', 'def check_static_ip(address, prefix, gateway):
    pass
', 'ipaddress.IPv4Network(f''{address}/{prefix}'', strict=False) даёт network_address, broadcast_address и проверку «in».', '{"func": "check_static_ip", "tests": [{"args": ["192.168.1.10", 24, "192.168.1.1"], "expected": "ok"}, {"args": ["192.168.1.10", 24, ""], "expected": "ok"}, {"args": ["192.168.1.0", 24, "192.168.1.1"], "expected": "address-is-network"}, {"args": ["192.168.1.255", 24, ""], "expected": "address-is-broadcast"}, {"args": ["192.168.1.10", 24, "192.168.2.1"], "expected": "gateway-outside"}, {"args": ["10.0.0.5", 24, "10.0.0.5"], "expected": "gateway-is-self"}, {"args": ["10.0.0.5", 24, "10.0.0.255"], "expected": "gateway-reserved"}, {"args": ["10.0.0.5", 24, "10.0.0.0"], "expected": "gateway-reserved"}, {"args": ["10.0.0.5", 31, ""], "expected": "bad-prefix"}, {"args": ["10.0.0.5", 0, ""], "expected": "bad-prefix"}, {"args": ["10.0.0.300", 24, ""], "expected": "bad-address"}, {"args": ["10.0.0.5", 24, "gw"], "expected": "bad-gateway"}, {"args": ["172.16.5.130", 25, "172.16.5.129"], "expected": "ok"}, {"args": ["172.16.5.130", 25, "172.16.5.1"], "expected": "gateway-outside"}, {"args": ["172.16.5.128", 25, ""], "expected": "address-is-network"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-bond-select', 5, 'func', 'Выбор режима бонда', 'Напишите функцию choose_bond_mode(switch, vm_network, need_speed), которая выбирает режим бонда (число 0..6). switch — как настроены порты коммутатора: "none" (ничего), "static" (статическая агрегация) или "lacp"; любое другое значение считайте "none". Допустимые режимы: всегда 1, 5, 6; при "static" ещё 0, 2, 3; при "lacp" ещё 4. Если vm_network равно True, режимы 0, 5, 6 исключаются. Затем берётся первый допустимый режим из списка предпочтений: при need_speed=True — [4, 2, 6, 5, 0, 3, 1], иначе — [1, 4, 2, 6, 5, 3, 0].', 'def choose_bond_mode(switch, vm_network, need_speed):
    pass
', 'Соберите множество допустимых режимов, затем пройдите по списку предпочтений.', '{"func": "choose_bond_mode", "tests": [{"args": ["none", false, false], "expected": 1}, {"args": ["none", false, true], "expected": 6}, {"args": ["none", true, true], "expected": 1}, {"args": ["static", true, true], "expected": 2}, {"args": ["static", false, true], "expected": 2}, {"args": ["lacp", true, false], "expected": 1}, {"args": ["lacp", true, true], "expected": 4}, {"args": ["static", false, false], "expected": 1}, {"args": ["weird", false, true], "expected": 6}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-qos-limiter', 6, 'func', 'Ограничитель скорости vNIC', 'Упрощённая модель QoS виртуальной сетевой карты: «ведро» токенов. Вначале в ведре burst токенов. На каждом шаге (секунде): ведро пополняется на average, но не выше burst; затем отправляется sent = min(demand, токены в ведре, peak); эти токены убираются из ведра. Лишний спрос пропадает (очередей нет). Напишите функцию qos_limiter(average, peak, burst, demands): demands — список спроса по шагам; верните список отправленного на каждом шаге.', 'def qos_limiter(average, peak, burst, demands):
    pass
', 'Храните одну переменную tokens и обновляйте её на каждом шаге в указанном порядке.', '{"func": "qos_limiter", "tests": [{"args": [10, 50, 30, [100, 100, 100, 100]], "expected": [30, 10, 10, 10]}, {"args": [10, 50, 100, [20, 20, 0, 0, 60, 60]], "expected": [20, 20, 0, 0, 50, 50]}, {"args": [5, 5, 5, [3, 3, 3]], "expected": [3, 3, 3]}, {"args": [0, 10, 20, [15, 15, 15]], "expected": [10, 10, 0]}, {"args": [10, 100, 10, []], "expected": []}, {"args": [100, 20, 1000, [50, 5]], "expected": [20, 5]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-bond-options', 7, 'func', 'Разбор опций бонда', 'Пользовательские опции бонда — строка из пар через пробел, например "mode=4 miimon=100 lacp_rate=fast". Имена режимов: balance-rr=0, active-backup=1, balance-xor=2, broadcast=3, 802.3ad=4, balance-tlb=5, balance-alb=6. Напишите функцию parse_bond_options(text): верните None, если выполнено хоть одно из условий: токен без «=» или с пустым именем или значением; нет mode; mode — не имя из списка и не цифра 0..6; значение miimon не состоит из цифр; lacp_rate задан не при режиме 4 или его значение не "slow" и не "fast". Иначе верните кортеж (номер режима, отсортированный по имени список кортежей (имя, значение) остальных опций). Если ключ повторён, побеждает последнее значение.', 'def parse_bond_options(text):
    pass
', 'Разберите токены в словарь, затем достаньте mode и проверьте остальное по порядку.', '{"func": "parse_bond_options", "tests": [{"args": ["mode=4 miimon=100 lacp_rate=fast"], "expected": {"__tuple__": [4, [{"__tuple__": ["lacp_rate", "fast"]}, {"__tuple__": ["miimon", "100"]}]]}}, {"args": ["mode=802.3ad xmit_hash_policy=layer2+3"], "expected": {"__tuple__": [4, [{"__tuple__": ["xmit_hash_policy", "layer2+3"]}]]}}, {"args": ["miimon=100"], "expected": null}, {"args": ["mode=7"], "expected": null}, {"args": ["mode=1 lacp_rate=fast"], "expected": null}, {"args": ["mode=active-backup primary=eth0"], "expected": {"__tuple__": [1, [{"__tuple__": ["primary", "eth0"]}]]}}, {"args": ["mode=1 miimon=abc"], "expected": null}, {"args": ["mode=2 mode=4"], "expected": {"__tuple__": [4, []]}}, {"args": ["mode=1 bogus"], "expected": null}, {"args": [""], "expected": null}, {"args": ["  mode=0   "], "expected": {"__tuple__": [0, []]}}, {"args": ["mode=4 lacp_rate=medium"], "expected": null}, {"args": ["mode="], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-host-plan', 8, 'func', 'Проверка сетевого плана хоста', 'План хоста — список кортежей (network, nic, vlan, is_vm): vlan равен None (сеть без метки) или числу. Напишите функцию validate_plan(attachments), которая возвращает отсортированный список уникальных строк-ошибок: "name-too-long:<сеть>" — is_vm истинно и имя сети длиннее 15 символов (имя bridge); "network-on-multiple-nics:<сеть>" — одна сеть привязана к разным картам; "bad-vlan:<сеть>" — vlan не None и не целое 1..4094; "multiple-untagged:<карта>" — на карте две и больше разных сетей без метки; "vlan-clash:<карта>.<vlan>" — на карте две и больше разных сетей с одним и тем же корректным vlan. Некорректные vlan в проверке vlan-clash не участвуют. Корректный план даёт пустой список.', 'def validate_plan(attachments):
    pass
', 'Заведите три словаря: карты по сетям, сети без метки по картам, сети по паре (карта, vlan); в конце соберите множество ошибок.', '{"func": "validate_plan", "tests": [{"args": [[]], "expected": []}, {"args": [[{"__tuple__": ["ovirtmgmt", "eth0", null, true]}, {"__tuple__": ["vm1", "eth0", 10, true]}, {"__tuple__": ["vm2", "eth0", 20, true]}]], "expected": []}, {"args": [[{"__tuple__": ["a", "eth0", null, true]}, {"__tuple__": ["b", "eth0", null, false]}]], "expected": ["multiple-untagged:eth0"]}, {"args": [[{"__tuple__": ["a", "eth1", 5, true]}, {"__tuple__": ["b", "eth1", 5, true]}]], "expected": ["vlan-clash:eth1.5"]}, {"args": [[{"__tuple__": ["a", "eth1", 5, true]}, {"__tuple__": ["a", "eth2", 5, true]}]], "expected": ["network-on-multiple-nics:a"]}, {"args": [[{"__tuple__": ["averyveryverylongname", "eth1", 9, true]}]], "expected": ["name-too-long:averyveryverylongname"]}, {"args": [[{"__tuple__": ["averyveryverylongname", "eth1", 9, false]}]], "expected": []}, {"args": [[{"__tuple__": ["x", "eth1", 0, true]}, {"__tuple__": ["y", "eth1", 5000, false]}]], "expected": ["bad-vlan:x", "bad-vlan:y"]}, {"args": [[{"__tuple__": ["a", "bond0", null, true]}, {"__tuple__": ["b", "bond0", null, true]}, {"__tuple__": ["c", "bond0", 7, true]}, {"__tuple__": ["d", "bond0", 7, false]}, {"__tuple__": ["e", "eth9", 4095, true]}]], "expected": ["bad-vlan:e", "multiple-untagged:bond0", "vlan-clash:bond0.7"]}, {"args": [[{"__tuple__": ["a", "eth0", 3, true]}, {"__tuple__": ["a", "eth0", 3, true]}]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-out-of-sync', 9, 'func', 'Поиск рассинхронизации', 'Менеджер хранит желаемую конфигурацию сетей хоста desired, а хост сообщает фактическую actual; обе — словари «сеть → словарь свойств» (например {"vlan": 10, "mtu": 1500}). Напишите функцию out_of_sync(desired, actual): верните список кортежей (сеть, список строк). Для сети из desired, которой нет в actual, список равен ["missing"]. Для сети, которая есть в обоих, список — отсортированные имена свойств из desired, значение которых в actual отличается или отсутствует (лишние свойства в actual игнорируются); сеть без отличий в ответ не попадает. Сеть, которая есть только в actual, даёт (сеть, ["unmanaged"]). Сначала идут сети из desired по алфавиту, затем только-actual по алфавиту.', 'def out_of_sync(desired, actual):
    pass
', 'Три прохода: по desired, по actual-only; различия — сравнение значений по ключам desired.', '{"func": "out_of_sync", "tests": [{"args": [{"a": {"vlan": 10, "mtu": 1500}}, {"a": {"vlan": 10, "mtu": 1500}}], "expected": []}, {"args": [{"a": {"vlan": 10, "mtu": 9000}}, {"a": {"vlan": 10, "mtu": 1500}}], "expected": [{"__tuple__": ["a", ["mtu"]]}]}, {"args": [{"a": {"vlan": 10, "bridged": true}}, {"a": {"vlan": 20, "mtu": 1500}}], "expected": [{"__tuple__": ["a", ["bridged", "vlan"]]}]}, {"args": [{"a": {}}, {}], "expected": [{"__tuple__": ["a", ["missing"]]}]}, {"args": [{}, {"z": {"vlan": 1}}], "expected": [{"__tuple__": ["z", ["unmanaged"]]}]}, {"args": [{"b": {"mtu": 1500}, "a": {"mtu": 1500}}, {"c": {}, "a": {"mtu": 9000}, "d": {}}], "expected": [{"__tuple__": ["a", ["mtu"]]}, {"__tuple__": ["b", ["missing"]]}, {"__tuple__": ["c", ["unmanaged"]]}, {"__tuple__": ["d", ["unmanaged"]]}]}, {"args": [{"a": {"vlan": null}}, {"a": {}}], "expected": [{"__tuple__": ["a", ["vlan"]]}]}, {"args": [{"a": {"vlan": 10}}, {"a": {"vlan": 10, "extra": 1}}], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-weighted-shares', 10, 'func', 'Доли канала между сетями', 'Host network QoS делит пропускную способность карты между сетями по весам (shares). Модель: «взвешенная максимально-минимальная справедливость». Напишите функцию weighted_shares(capacity, demands, weights): demands — словарь «сеть → спрос», weights — «сеть → вес» (положительное число для каждой сети из demands). Пока осталась ёмкость и есть неудовлетворённые сети: каждой неудовлетворённой сети полагается доля остатка, пропорциональная её весу; сети, чей спрос не превышает долю, получают ровно спрос и выходят из дележа, а освободившаяся ёмкость делится дальше; если спрос не превышает долю ни у кого, все оставшиеся получают свои доли и дележ заканчивается. Сеть с нулевым спросом получает 0. Верните словарь «сеть → выделенная скорость», каждое значение — float, округлённое до 3 знаков.', 'def weighted_shares(capacity, demands, weights):
    pass
', 'Цикл: считайте доли активных сетей от остатка; насыщенных уберите и вычтите их спрос из остатка; если насыщенных нет, раздайте доли и остановитесь.', '{"func": "weighted_shares", "tests": [{"args": [100, {"a": 80, "b": 80}, {"a": 1, "b": 1}], "expected": {"a": 50.0, "b": 50.0}}, {"args": [100, {"a": 10, "b": 80, "c": 80}, {"a": 1, "b": 1, "c": 1}], "expected": {"a": 10.0, "b": 45.0, "c": 45.0}}, {"args": [100, {"a": 100, "b": 100}, {"a": 1, "b": 3}], "expected": {"a": 25.0, "b": 75.0}}, {"args": [100, {"a": 20, "b": 100, "c": 100}, {"a": 1, "b": 2, "c": 2}], "expected": {"a": 20.0, "b": 40.0, "c": 40.0}}, {"args": [1000, {"a": 5, "b": 7}, {"a": 1, "b": 1}], "expected": {"a": 5.0, "b": 7.0}}, {"args": [30, {"a": 0, "b": 50}, {"a": 1, "b": 1}], "expected": {"a": 0.0, "b": 30.0}}, {"args": [10, {"a": 100, "b": 100, "c": 100}, {"a": 1, "b": 1, "c": 1}], "expected": {"a": 3.333, "b": 3.333, "c": 3.333}}, {"args": [0, {"a": 10, "b": 10}, {"a": 1, "b": 1}], "expected": {"a": 0.0, "b": 0.0}}, {"args": [90, {"a": 10, "b": 30, "c": 100}, {"a": 1, "b": 1, "c": 1}], "expected": {"a": 10.0, "b": 30.0, "c": 50.0}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-ovn-acl', 11, 'func', 'Вердикт списка доступа OVN', 'Группы безопасности OVN превращаются в ACL. Модель: acls — список кортежей (priority, direction, action, proto, port_min, port_max, cidr). direction — "ingress" или "egress"; action — "allow" или "drop"; proto — "tcp", "udp", "icmp" или "any"; port_min и port_max — границы порта включительно или None (любой порт; для icmp пакет приходит с port=None); cidr — сеть в виде "10.0.0.0/8" или "any". Правило подходит пакету (direction, proto, port, remote), если совпало направление, протокол (правило "any" подходит любому), порт попал в границы (правило с границами не подходит пакету с port=None) и адрес remote лежит в cidr (допускается и IPv6). Из подходящих правил побеждает правило с наибольшим priority; при равных priority побеждает "drop". Если подходящих нет, вердикт "drop". Напишите функцию packet_verdict(acls, direction, proto, port, remote), которая возвращает "allow" или "drop".', 'def packet_verdict(acls, direction, proto, port, remote):
    pass
', 'Для каждого правила проверьте условия подряд, подходящие сравнивайте по ключу (priority, действие == drop); ipaddress.ip_address(remote) in ipaddress.ip_network(cidr).', '{"func": "packet_verdict", "tests": [{"args": [[{"__tuple__": [100, "ingress", "allow", "tcp", 22, 22, "10.0.0.0/8"]}, {"__tuple__": [100, "ingress", "allow", "tcp", 443, 443, "any"]}, {"__tuple__": [200, "ingress", "drop", "any", null, null, "10.9.0.0/16"]}], "ingress", "tcp", 22, "10.1.1.1"], "expected": "allow"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "tcp", 22, 22, "10.0.0.0/8"]}, {"__tuple__": [100, "ingress", "allow", "tcp", 443, 443, "any"]}, {"__tuple__": [200, "ingress", "drop", "any", null, null, "10.9.0.0/16"]}], "ingress", "tcp", 22, "192.168.1.1"], "expected": "drop"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "tcp", 22, 22, "10.0.0.0/8"]}, {"__tuple__": [100, "ingress", "allow", "tcp", 443, 443, "any"]}, {"__tuple__": [200, "ingress", "drop", "any", null, null, "10.9.0.0/16"]}], "ingress", "tcp", 443, "192.168.1.1"], "expected": "allow"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "tcp", 22, 22, "10.0.0.0/8"]}, {"__tuple__": [100, "ingress", "allow", "tcp", 443, 443, "any"]}, {"__tuple__": [200, "ingress", "drop", "any", null, null, "10.9.0.0/16"]}], "ingress", "tcp", 22, "10.9.1.1"], "expected": "drop"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "tcp", 22, 22, "10.0.0.0/8"]}, {"__tuple__": [100, "ingress", "allow", "tcp", 443, 443, "any"]}, {"__tuple__": [200, "ingress", "drop", "any", null, null, "10.9.0.0/16"]}], "egress", "tcp", 443, "1.1.1.1"], "expected": "drop"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "tcp", 22, 22, "10.0.0.0/8"]}, {"__tuple__": [100, "ingress", "allow", "tcp", 443, 443, "any"]}, {"__tuple__": [200, "ingress", "drop", "any", null, null, "10.9.0.0/16"]}], "ingress", "icmp", null, "10.1.1.1"], "expected": "drop"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "any", null, null, "any"]}, {"__tuple__": [100, "ingress", "drop", "udp", 53, 53, "any"]}], "ingress", "udp", 53, "8.8.8.8"], "expected": "drop"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "any", null, null, "any"]}, {"__tuple__": [100, "ingress", "drop", "udp", 53, 53, "any"]}], "ingress", "udp", 54, "8.8.8.8"], "expected": "allow"}, {"args": [[{"__tuple__": [100, "ingress", "allow", "any", null, null, "any"]}, {"__tuple__": [100, "ingress", "drop", "udp", 53, 53, "any"]}], "ingress", "tcp", 53, "8.8.8.8"], "expected": "allow"}, {"args": [[{"__tuple__": [10, "egress", "allow", "tcp", 1000, 2000, "any"]}], "egress", "tcp", 2001, "1.2.3.4"], "expected": "drop"}, {"args": [[{"__tuple__": [10, "egress", "allow", "tcp", 1000, 2000, "any"]}], "egress", "tcp", 1000, "1.2.3.4"], "expected": "allow"}, {"args": [[{"__tuple__": [10, "ingress", "allow", "icmp", null, null, "any"]}], "ingress", "icmp", null, "5.5.5.5"], "expected": "allow"}, {"args": [[{"__tuple__": [10, "ingress", "allow", "any", null, null, "fd00::/8"]}], "ingress", "tcp", 80, "fd12::1"], "expected": "allow"}, {"args": [[{"__tuple__": [10, "ingress", "allow", "any", null, null, "fd00::/8"]}], "ingress", "tcp", 80, "10.0.0.1"], "expected": "drop"}, {"args": [[{"__tuple__": [5, "ingress", "drop", "any", null, null, "any"]}, {"__tuple__": [50, "ingress", "allow", "tcp", 80, 80, "10.0.0.0/24"]}], "ingress", "tcp", 80, "10.0.0.7"], "expected": "allow"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-ovn-assign', 12, 'func', 'Выдача адресов портам OVN', 'Логический коммутатор OVN раздаёт адреса портам из подсети. Первый пригодный к использованию адрес подсети зарезервирован за шлюзом (логическим маршрутизатором). Напишите функцию assign_addresses(cidr, existing, ports): existing — словарь «порт → уже выданный адрес», ports — список имён портов, которым нужны адреса. Верните словарь «порт → адрес (строка)» для всех портов из ports: порт, уже имеющий адрес в existing, сохраняет его; остальным по порядку списка выдаётся наименьший свободный адрес хоста подсети (кроме адреса шлюза и всех адресов из значений existing, включая порты, которых нет в ports); повтор порта в ports получает тот же адрес. Если свободных адресов не осталось, порт получает пустую строку. Пригодные адреса — это net.hosts() из модуля ipaddress.', 'def assign_addresses(cidr, existing, ports):
    pass
', 'net.hosts() — генератор: первый элемент отдайте шлюзу, остальные отфильтруйте по занятым и берите next(..., '''').', '{"func": "assign_addresses", "tests": [{"args": ["10.0.0.0/24", {}, ["p1", "p2"]], "expected": {"p1": "10.0.0.2", "p2": "10.0.0.3"}}, {"args": ["10.0.0.0/24", {"p1": "10.0.0.2"}, ["p1", "p2"]], "expected": {"p1": "10.0.0.2", "p2": "10.0.0.3"}}, {"args": ["10.0.0.0/24", {"x": "10.0.0.2", "y": "10.0.0.4"}, ["a", "b", "c"]], "expected": {"a": "10.0.0.3", "b": "10.0.0.5", "c": "10.0.0.6"}}, {"args": ["10.0.0.0/30", {}, ["a", "b", "c"]], "expected": {"a": "10.0.0.2", "b": "", "c": ""}}, {"args": ["10.0.0.0/29", {}, ["a", "a"]], "expected": {"a": "10.0.0.2"}}, {"args": ["10.0.0.0/29", {}, ["a", "b", "c", "d", "e", "f"]], "expected": {"a": "10.0.0.2", "b": "10.0.0.3", "c": "10.0.0.4", "d": "10.0.0.5", "e": "10.0.0.6", "f": ""}}, {"args": ["192.168.5.64/26", {}, ["p"]], "expected": {"p": "192.168.5.66"}}, {"args": ["10.0.0.0/24", {"p": "10.0.0.9"}, []], "expected": {}}, {"args": ["10.0.0.0/24", {"p": "10.0.0.2"}, ["q"]], "expected": {"q": "10.0.0.3"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ov21-setup-networks', 13, 'func', 'setupNetworks с откатом', 'Смоделируйте атомарную операцию setupNetworks. Конфигурация хоста current — словарь «сеть → (карта, vlan)», vlan равен None или числу. ops — список правок-кортежей: ("add", сеть, карта, vlan), ("remove", сеть), ("move", сеть, карта, vlan). Правки применяются по порядку к копии конфигурации. Правка отклоняется, если: add для уже существующей сети; remove или move для несуществующей; неизвестный вид правки; vlan не None и не целое 1..4094; после правки на какой-то карте оказалось две и больше сети без метки. При первой отклонённой правке с индексом i верните ("rejected:i", current) — конфигурация не меняется. Если все правки приняты и check=True, проверяется связь: сеть "ovirtmgmt" должна существовать, а её карта входить в список up_nics; иначе верните ("reverted", current). Иначе верните ("applied", новая конфигурация). Сигнатура: apply_setup_networks(current, ops, up_nics, check).', 'def apply_setup_networks(current, ops, up_nics, check):
    pass
', 'Копируйте current в новый словарь, применяйте правки циклом с enumerate, после каждой проверяйте инварианты; откат — это возврат исходного current.', '{"func": "apply_setup_networks", "tests": [{"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["add", "vm2", "eth0", 20]}], ["eth0", "eth1"], true], "expected": {"__tuple__": ["applied", {"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}, "vm2": {"__tuple__": ["eth0", 20]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["add", "vm2", "eth0", null]}], ["eth0", "eth1"], true], "expected": {"__tuple__": ["rejected:0", {"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["add", "vm2", "eth0", 20]}, {"__tuple__": ["remove", "nothere"]}], ["eth0", "eth1"], true], "expected": {"__tuple__": ["rejected:1", {"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["move", "ovirtmgmt", "eth2", null]}], ["eth0", "eth1"], true], "expected": {"__tuple__": ["reverted", {"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["move", "ovirtmgmt", "eth2", null]}], ["eth0", "eth1"], false], "expected": {"__tuple__": ["applied", {"ovirtmgmt": {"__tuple__": ["eth2", null]}, "vm1": {"__tuple__": ["eth0", 10]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["remove", "ovirtmgmt"]}], ["eth0"], true], "expected": {"__tuple__": ["reverted", {"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["remove", "ovirtmgmt"]}], ["eth0"], false], "expected": {"__tuple__": ["applied", {"vm1": {"__tuple__": ["eth0", 10]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}}, [{"__tuple__": ["move", "ovirtmgmt", "eth1", null]}, {"__tuple__": ["add", "x", "eth0", null]}], ["eth0", "eth1"], true], "expected": {"__tuple__": ["applied", {"ovirtmgmt": {"__tuple__": ["eth1", null]}, "x": {"__tuple__": ["eth0", null]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}}, [{"__tuple__": ["add", "x", "eth0", null]}, {"__tuple__": ["move", "ovirtmgmt", "eth1", null]}], ["eth0", "eth1"], true], "expected": {"__tuple__": ["rejected:0", {"ovirtmgmt": {"__tuple__": ["eth0", null]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}, [{"__tuple__": ["add", "vm1", "eth1", 5]}], ["eth0"], true], "expected": {"__tuple__": ["rejected:0", {"ovirtmgmt": {"__tuple__": ["eth0", null]}, "vm1": {"__tuple__": ["eth0", 10]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}}, [{"__tuple__": ["add", "bad", "eth1", 4095]}], ["eth0"], true], "expected": {"__tuple__": ["rejected:0", {"ovirtmgmt": {"__tuple__": ["eth0", null]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}}, [{"__tuple__": ["rename", "ovirtmgmt", "x"]}], ["eth0"], true], "expected": {"__tuple__": ["rejected:0", {"ovirtmgmt": {"__tuple__": ["eth0", null]}}]}}, {"args": [{"ovirtmgmt": {"__tuple__": ["eth0", null]}}, [], ["eth0"], true], "expected": {"__tuple__": ["applied", {"ovirtmgmt": {"__tuple__": ["eth0", null]}}]}}, {"args": [{}, [{"__tuple__": ["add", "a", "eth0", 1]}], ["eth0"], true], "expected": {"__tuple__": ["reverted", {}]}}]}');
